(function(){"use strict";app.factory("politicaService",function(t){const n=t.get("mainService"),e="Config/Politica/",i={get:function(t){return n.getData("get",e+"?json="+JSON.stringify(t),null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let n=JSON.parse(t.payload)||[];return n}})},save:function(t){return n.getData("post",`${e}?json=${JSON.stringify(t)}`,null,!0)},update:function(t,i){return n.getData("put",`${e}${t}?json=${JSON.stringify(i)}`,null,!0)},delete:function(t){return n.getData("delete",e+t,null,!0)}};return i})})(window.angular);